function respond($data, int $status = 200): void { http_response_code($status); echo json_encode($data, JSON_UNESCAPED_UNICODE | JSON_INVALID_UTF8_SUBSTITUTE); exit; }
function fail(string $message, int $status = 422): void { respond(['error' => $message], $status); }
function isIntValue($value, int $min, int $max): bool { return is_int($value) && $value >= $min && $value <= $max; }
function bodyJson(): array { try { $value=json_decode(file_get_contents('php://input'),true,32,JSON_THROW_ON_ERROR); } catch (JsonException $e) { fail('JSON inválido.'); } if (!is_array($value)) fail('Envía un objeto JSON.'); return $value; }
function audit(PDO $db, string $action, string $entity, ?int $entityId, array $details = []): void { $stmt=$db->prepare('INSERT INTO audit_log(user_id,action,entity,entity_id,details,created_at) VALUES(?,?,?,?,?,?)'); $stmt->execute([$_SESSION['user']['id']??null,$action,$entity,$entityId,json_encode($details,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE),date('Y-m-d H:i:s')]); }
function currentUser(PDO $db): ?array { if (!isset($_SESSION['user']['id'])) return null; $stmt=$db->prepare('SELECT u.id,u.username,u.name,u.role_id,r.name AS role FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=? AND u.active=1'); $stmt->execute([$_SESSION['user']['id']]); $user=$stmt->fetch(); if(!$user){unset($_SESSION['user']);return null;} $_SESSION['user']=$user; return $user; }
function requireUser(PDO $db, array $roles = ['Administrador','Cajero']): array { $user=currentUser($db); if(!$user) fail('Inicia sesión para continuar.',401); if(!in_array($user['role'],$roles,true)) fail('No tienes permiso para esta operación.',403); return $user; }
function requireCsrf(): void { if (!hash_equals($_SESSION['csrf']??'missing',$_SERVER['HTTP_X_CSRF_TOKEN']??'')) fail('La sesión expiró. Recarga la página.',403); }
function pageArgs(): array { $page=filter_var($_GET['page']??1,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:1; $limit=min(100,max(1,filter_var($_GET['limit']??20,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:20)); return [$page,$limit]; }
function pageResult(PDO $db, string $sql, string $countSql, array $params): array { [$page,$limit]=pageArgs(); $count=$db->prepare($countSql);$count->execute($params);$total=(int)$count->fetchColumn();$query=$db->prepare($sql.' LIMIT :limit OFFSET :offset');foreach($params as $key=>$value)$query->bindValue($key,$value);$query->bindValue(':limit',$limit,PDO::PARAM_INT);$query->bindValue(':offset',($page-1)*$limit,PDO::PARAM_INT);$query->execute();return ['data'=>$query->fetchAll(),'page'=>$page,'limit'=>$limit,'total'=>$total,'total_pages'=>(int)ceil($total/$limit)]; }
function cleanDateRange(): array { $from=$_GET['from']??date('Y-m-d');$to=$_GET['to']??date('Y-m-d');foreach([$from,$to] as $date)if(!is_string($date)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||!strtotime($date))fail('Usa fechas válidas con formato AAAA-MM-DD.');if($from>$to)fail('La fecha inicial debe ser anterior a la final.');if((strtotime($to)-strtotime($from))/86400>366)fail('El intervalo máximo del reporte es de 366 días.');return [$from.' 00:00:00',$to.' 23:59:59']; }
